using SchoolERP.Application.Features.ClassSections;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;using SchoolERP.Domain.Exceptions;using Xunit;
namespace SchoolERP.UnitTests;public sealed class ClassSectionManagementTests{[Fact]public void Request_has_no_caller_controlled_ownership(){var p=typeof(CreateClassSectionRequest).GetProperties().Select(x=>x.Name);Assert.DoesNotContain("TenantId",p);Assert.DoesNotContain("SchoolId",p);Assert.DoesNotContain("AcademicYearId",p);Assert.DoesNotContain("SchoolClassId",p);}[Fact]public void Create_derives_complete_ownership_and_normalizes(){var t=Guid.NewGuid();var s=Guid.NewGuid();var y=Guid.NewGuid();var c=Guid.NewGuid();var x=ClassSection.Create(t,s,y,c," Section A "," sec_a ",1,30,room:" 101 ");Assert.Equal(ClassSectionStatus.Draft,x.Status);Assert.Equal((t,s,y,c),(x.TenantId,x.SchoolId,x.AcademicYearId,x.SchoolClassId));Assert.Equal("SEC_A",x.Code);Assert.Equal(1,x.DisplayOrder);Assert.Equal(30,x.Capacity);Assert.Equal("101",x.RoomNumber);}[Theory][InlineData(null)][InlineData(1)][InlineData(500)]public void Valid_capacities_are_accepted(int? capacity)=>Assert.Equal(capacity,ClassSection.Create(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),"A","A",0,capacity).Capacity);[Theory][InlineData(0)][InlineData(-1)][InlineData(501)]public void Invalid_capacities_are_rejected(int capacity)=>Assert.Throws<DomainException>(()=>ClassSection.Create(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),"A","A",0,capacity));[Theory][InlineData("A B")][InlineData("A@B")][InlineData("")]public void Invalid_codes_are_rejected(string code)=>Assert.Throws<DomainException>(()=>ClassSection.NormalizeCode(code));[Fact]public void Lifecycle_and_archived_read_only_are_enforced(){var x=ClassSection.Create(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),"A","A",0);x.Activate(DateTime.UtcNow);Assert.Throws<DomainException>(()=>x.Archive(DateTime.UtcNow));x.Deactivate(DateTime.UtcNow);x.Archive(DateTime.UtcNow);Assert.Throws<DomainException>(()=>x.UpdateDetails("B",null,0,null,null,null,DateTime.UtcNow));}}
